        public static List<PrePrimaryProgressReportSubSubjects> GetAllConfiguredPrePrimarySubSubjects(int aiSchoolId, int aiAcademicYrID, int aiStandardId, string sortExpression, int iEndIndex, int iStartIndex)
        {
            List<PrePrimaryProgressReportSubSubjects> olstclsSubSubjects = new List<PrePrimaryProgressReportSubSubjects>();
            string sSortExpression = "";
            if (sortExpression != "")
                sSortExpression = " ORDER BY " + sortExpression;
            else
                sSortExpression = " ORDER BY ModuleName";

            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
            {
                oSQLServerDbUtility.AddParameter("SchoolId", aiSchoolId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("AcademicYrId", aiAcademicYrID, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("StandardId", aiStandardId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("StartIndex", iStartIndex, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("EndIndex", iEndIndex, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("SortExp", sSortExpression, SqlDbType.NVarChar);

                using (SqlDataReader oSqlDataReader = oSQLServerDbUtility.ExecuteStoredProcedureAndGetresult("usp_GetSubSubjectsForStandards"))
                {
                    PrePrimaryProgressReportSubSubjects oPrePrimaryProgressReportSubSubjects;
                    while (oSqlDataReader.Read())
                    {
                        oPrePrimaryProgressReportSubSubjects = new PrePrimaryProgressReportSubSubjects
                        {
                            SubSubjectName = Convert.ToString(oSqlDataReader["SubSubjectName"]),
                            SubjectName = Convert.ToString(oSqlDataReader["SubjectName"]),
                            ModuleName = Convert.ToString(oSqlDataReader["ModuleName"]),
                            SubSubjectID = Convert.ToInt32(oSqlDataReader["SubSubjectID"]),
                            SubjectID = oSqlDataReader["SubjectID"] != System.DBNull.Value ? Convert.ToInt32(oSqlDataReader["SubjectID"]) : 0,
                            ModuleID = Convert.ToInt32(oSqlDataReader["ModuleID"]),
                        };
                        olstclsSubSubjects.Add(oPrePrimaryProgressReportSubSubjects);
                    }
                }
            }
            return olstclsSubSubjects;         
            
        }

