        public void GetPrePrimaryStandardsAndModuleName(int aiSchoolId, int aiAcademicYr)
        {
            string sSelectStatement = " SELECT  " +
                                 " school_id " +
                                 " , original_standard_id " +
                                 " , standard_id " +
                                 " , standard_name " +
                             " FROM " +
                                  " standard_master " +
                             " WHERE " +
                                  " is_deleted = N'" + Constants.C_NO + "'" +
                                  " AND is_preprimary = N'" + Constants.C_YES + "'" +
                                  " AND school_id = " + aiSchoolId +
                                  " AND academic_year_id = " + aiAcademicYr +
                                  " AND standard_id IN (SELECT Standard_Id " +
                                                        "FROM PrePrimaryStandardForNewProgressReport " +
                                                        " WHERE School_id = " + aiSchoolId +
                                                        " AND Academic_Year_Id = " + aiAcademicYr +
                                                        " AND Is_Deleted=0)" +
                              " ORDER BY " +
                                   " original_standard_id";

            sSelectStatement += " Select ExamModuleId,ExamModuleName FROM PrePrimaryProgressReportModuleConfigList " +
                                " where is_deleted = 0  AND School_Id = " + aiSchoolId +
                                  " AND Academic_Year_Id = " + aiAcademicYr;

            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
            {
                using (SqlDataReader oSqlDataReader = oSQLServerDbUtility.ExecuteSqlStatementAndGetResults(sSelectStatement))
                {
                    FillPrePrimaryStandardsEntityList(oSqlDataReader);
                    if (oSqlDataReader.NextResult())
                        FillPrePrimaryModuleEntityList(oSqlDataReader);
                }
            }
        }
