                                          ", " + moPrePrimaryProgressReportSubSubjectsEntity.ModuleID +
                                          ", " + moPrePrimaryProgressReportSubSubjectsEntity.SubjectID +
                                           ", " + moPrePrimaryProgressReportSubSubjectsEntity.StandardID +
                                           ", " + moPrePrimaryProgressReportSubSubjectsEntity.SchoolId +
                                           ", " + moPrePrimaryProgressReportSubSubjectsEntity.AcademicYearId +
                                           ", dbo.GetLocalDate(DEFAULT) " +
                                           ", ISNULL((SELECT MAX(SortOrder)+1 FROM PrePrimaryProgressReportSubSubjects WHERE ExamModuleId = " + moPrePrimaryProgressReportSubSubjectsEntity.ModuleID +
                                                                                                                       " AND PrePrimaryProgressReportSubjectId = " + moPrePrimaryProgressReportSubSubjectsEntity.SubjectID +
                                                                                                                       " AND Standard_Id = " + moPrePrimaryProgressReportSubSubjectsEntity.StandardID +
                                                                                                                       " AND School_Id = " + moPrePrimaryProgressReportSubSubjectsEntity.SchoolId +
                                                                                                                       " AND Academic_Year_Id = " + moPrePrimaryProgressReportSubSubjectsEntity.AcademicYearId + "),0) " +
                                            ", " + moPrePrimaryProgressReportSubSubjectsEntity.InsertedById +                                                                            
                                           " ) ";

            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
                oSQLServerDbUtility.ExecuteTransaction(sInsertStatement);
        }

