        public void GetPrePrimaryProgressSheetDetailsOfStudent(int aiSchoolId, int aiAcademicYearId, int aiStudentId)
        {
            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
            {
                oSQLServerDbUtility.AddParameter("SchoolId", aiSchoolId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("AcademicYrId", aiAcademicYearId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("StudentId", aiStudentId, SqlDbType.Int);

                using (SqlDataReader oSqlDataReader = oSQLServerDbUtility.ExecuteStoredProcedureAndGetresult("usp_GetAllPrePrimaryProgressReportDetailsOfStudent"))
                {
                    FillMonthConfigurationEntityList(oSqlDataReader);
                    if (oSqlDataReader.NextResult())
                        FillRemarksEntityList(oSqlDataReader);
                    if (oSqlDataReader.NextResult())
                        FillSubSubjectsWithoutSubjectsEntityList(oSqlDataReader);
                    if (oSqlDataReader.NextResult())
                        FillSubSubjectsWithSubjectsEntityList(oSqlDataReader);
                    if (oSqlDataReader.NextResult())
                        FillStudentsExamResultWithSubjectsEntityList(oSqlDataReader);
                    if (oSqlDataReader.NextResult())
                        FillStudentsExamResultWithOutSubjectsEntityList(oSqlDataReader);
                    if (oSqlDataReader.NextResult())
                        FillPrePrimaryModuleEntityList(oSqlDataReader);
                    if (oSqlDataReader.NextResult())
                        FillStudentEntity(oSqlDataReader);
                    if (oSqlDataReader.NextResult())
                        FillCommentsEntity(oSqlDataReader);

                }
            }
        }

